"""Append stable construction IDs and produce a shared content table (no terrain edits)."""
from pathlib import Path
r=Path(__file__).resolve().parents[1]
woods=[('Oak','Planks','Log',13),('Birch','BirchPlanks','BirchLog',28),('Spruce','SprucePlanks','SpruceLog',59),('Jungle','JunglePlanks','JungleLog',62),('Acacia','AcaciaPlanks','AcaciaLog',65),('DarkOak','DarkOakPlanks','DarkOakLog',68)]
# Textures are resolved from existing definitions, not hardcoded family offsets.
woodshapes=['Stairs','Slab','Fence','FenceGate','Trapdoor','Door','StrippedLog','Button','PressurePlate','Table','Chair','Bench','Sign','Shelf']
stone=['Cobblestone','Stone','StoneBricks','MossyCobblestone','MossyStoneBricks','Bricks','Sandstone','Deepslate','PolishedGranite','PolishedDiorite','PolishedAndesite']
entries=[]
for family,planks,log,tile in woods:
 for shape in woodshapes:
  name=family+shape;material=log if shape=='StrippedLog' else planks
  entries.append((name,shape,material,planks))
for material in stone:
 for shape in ['Stairs','Slab','Wall']:entries.append((('StoneCutSlab' if material=='Stone' and shape=='Slab' else material+shape),shape,material,material))
for name,material in [('ChiseledStoneBricks','StoneBricks'),('SmoothStone','Stone'),('SmoothSandstone','Sandstone'),('CutSandstone','Sandstone'),('PolishedDeepslate','Deepslate'),('DeepslateBricks','Deepslate'),('CrackedDeepslateBricks','Deepslate'),('RoofShingles','Bricks')]:entries.append((name,'Cube',material,material))
for name,shape,material,ingredient in [('GlassPane','Pane','Glass','Glass'),('RoseGlassPane','Pane','Glass','Glass'),('AmberGlassPane','Pane','Glass','Glass'),('SmokedGlassPane','Pane','Glass','Glass'),('Lantern','Lantern','IronBlock','IronIngot'),('Chain','Chain','IronBlock','IronIngot'),('Candle','Candle','Wool','Wool'),('Campfire','Campfire','Log','Log'),('Bed','Bed','Planks','Wool'),('Barrel','Barrel','Planks','Planks'),('Painting','Painting','Planks','Wool'),('ItemFrame','Frame','Planks','Leather'),('FlowerPot','Pot','Bricks','Brick'),('Carpet','Carpet','Wool','Wool'),('DirtPath','Path','Dirt','Dirt'),('StonePaving','Cube','StoneBricks','StoneBricks'),('Scaffold','Scaffold','Bamboo','Bamboo')]:entries.append((name,shape,material,ingredient))
# Wool is an item but no historical wool block; new pieces resolve its material tile themselves.
for file,enum in [('include/Block.h','Block'),('include/Survival.h','Item')]:
 p=r/file;s=p.read_text();a=s.index('enum class '+enum);end=s.index('    Count',a)
 marker=s.find('    // v2.16.0: stable types;',a,end)
 if marker>=0:
  existing=[x.strip() for x in s[marker:].split('\n',1)[1].split('    Count',1)[0].strip().split(',') if x.strip()]
  if existing!=[e[0] for e in entries]:raise RuntimeError('Existing stable construction IDs differ; do not reorder them')
  continue
 s=s[:end]+'    // v2.16.0: stable types; orientation and connections are properties.\n    '+', '.join(e[0] for e in entries)+',\n'+s[end:];p.write_text(s)
lines=['// Generated by tools/generate_building_registry.py; append only.']
for name,shape,material,ingredient in entries:
 source='Block::'+material if material!='Wool' else 'Block::HayBale'
 lines.append(f'BUILDING({name}, {shape}, {source}, Item::{ingredient})')
(r/'include/BuildingContent.inc').write_text('\n'.join(lines)+'\n')
print(len(entries),'construction types appended')
